     7	
     8	/** Texto e título do documento emitido para uma reserva paga. */
     9	public interface DocumentTemplate {
    10	    String title();
    11	
    12	    String render(ReservationDocument d);
    13	
    14	    DocumentTemplate COMPROVANTE = new DocumentTemplate() {
    15	        public String title() { return "Comprovante de reserva"; }
    16	
    17	        public String render(ReservationDocument d) {
    18	            List<String> l = new ArrayList<>();
    19	            l.add(title() + " nº " + d.reservationId());
    20	            l.add("Hóspede: " + d.guestName() + " (CPF " + d.identity().cpf() + ")");
    21	            ptBody(l, d);
    22	            return String.join("\n", l);
    23	        }
    24	    };
    25	
    26	    DocumentTemplate FATURA = new DocumentTemplate() {
    27	        public String title() { return "Fatura de hospedagem"; }
    28	
    29	        public String render(ReservationDocument d) {
    30	            List<String> l = new ArrayList<>();
    31	            l.add(title() + " nº " + d.reservationId());
    32	            l.add("Empresa: " + d.identity().companyName() + " (CNPJ " + d.identity().cnpj() + ")");
    33	            l.add("Hóspede: " + d.guestName());
    34	            ptBody(l, d);
    35	            l.add("ISS retido (5%): " + Money.brl(Money.round(d.total().multiply(new java.math.BigDecimal("0.05")))));
    36	            return String.join("\n", l);
    37	        }
    38	    };
    39	
    40	    DocumentTemplate BOOKING_RECEIPT = new DocumentTemplate() {
    41	        public String title() { return "Booking receipt"; }
    42	
    43	        public String render(ReservationDocument d) {
    44	            DateTimeFormatter iso = DateTimeFormatter.ISO_LOCAL_DATE;
    45	            List<String> l = new ArrayList<>();
    46	            l.add(title() + " no. " + d.reservationId());
    47	            l.add("Guest: " + d.guestName() + " (passport " + d.identity().passport() + ", "
    48	                    + d.identity().country() + ")");
    49	            l.add("Room: " + d.roomNumber() + " (" + d.roomType() + ")");
    50	            l.add("Check-in: " + iso.format(d.checkIn()) + " | Check-out: " + iso.format(d.checkOut())
    51	                    + " | " + d.nights() + (d.nights() == 1 ? " night" : " nights"));
    52	            l.add("Nights: " + Money.brlEn(d.subtotal()));
    53	            if (d.discount().signum() > 0) l.add("Discount: " + Money.brlEn(d.discount()));
    54	            l.add("Total: " + Money.brlEn(d.total()));
    55	            return String.join("\n", l);
    56	        }
    57	    };
    58	
    59	    /** Linhas em português comuns ao comprovante e à fatura: quarto, datas, diárias, desconto, total. */
    60	    private static void ptBody(List<String> l, ReservationDocument d) {
    61	        DateTimeFormatter br = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    62	        l.add("Quarto: " + d.roomNumber() + " (" + d.roomType() + ")");
    63	        l.add("Entrada: " + br.format(d.checkIn()) + " | Saída: " + br.format(d.checkOut())
    64	                + " | " + d.nights() + (d.nights() == 1 ? " diária" : " diárias"));
    65	        l.add("Diárias: " + Money.brl(d.subtotal()));
    66	        if (d.discount().signum() > 0) l.add("Desconto: " + Money.brl(d.discount()));
    67	        l.add("Total: " + Money.brl(d.total()));
    68	    }
    69	}
=== IdentityReader
     1	package com.pousadamaretalta;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.function.Function;
     7	
     8	/** Lê do corpo da requisição os campos de identificação; exige exatamente um conjunto. */
     9	public final class IdentityReader {
    10	    private record Kind(List<String> fields, Function<List<String>, GuestIdentity> build) {}
    11	
    12	    private static final List<Kind> ALL = List.of(
    13	            new Kind(List.of("guestCpf"), v -> new GuestIdentity.Person(v.get(0))),
    14	            new Kind(List.of("companyCnpj", "companyName"), v -> new GuestIdentity.Company(v.get(0), v.get(1))),
    15	            new Kind(List.of("guestPassport", "guestCountry"), v -> new GuestIdentity.Foreigner(v.get(0), v.get(1))));
    16	
    17	    private IdentityReader() {}
    18	
    19	    public static GuestIdentity read(JsonNode body) {
    20	        GuestIdentity found = null;
    21	        for (Kind kind : ALL) {
    22	            List<String> values = new ArrayList<>();
    23	            int present = 0;
    24	            for (String f : kind.fields()) {
    25	                String v = Json.optionalText(body, f);
    26	                if (v != null) present++;
    27	                values.add(v);
    28	            }
    29	            if (present == 0) continue;
    30	            if (present != kind.fields().size() || found != null) {
    31	                throw ApiException.invalid("Informe apenas um modo de identificação completo: guestCpf, "
    32	                        + "companyCnpj + companyName, ou guestPassport + guestCountry");
    33	            }
    34	            found = kind.build().apply(values);
    35	        }
    36	        if (found == null) {
    37	            throw ApiException.invalid("Identificação ausente: informe guestCpf, companyCnpj + companyName, "
    38	                    + "ou guestPassport + guestCountry");
    39	        }
    40	        return found;
    41	    }
    42	}
