     1	package com.pousadamaretalta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public class Reservation {
     7	    public final int id;
     8	    public final Room room;
     9	    public final String guestName;
    10	    public final String guestEmail;
    11	    public final GuestIdentity identity;
    12	    public final LocalDate checkIn;
    13	    public final LocalDate checkOut;
    14	    public final int guests;
    15	    public final RatePlan ratePlan;
    16	    public final Pricing.Quote quote;
    17	
    18	    ReservationStatus status = ReservationStatus.PENDING;
    19	    BigDecimal amountPaid = Money.ZERO;
    20	    BigDecimal refund; // null até o cancelamento
    21	
    22	    Reservation(int id, Room room, String guestName, String guestEmail, GuestIdentity identity,
    23	                LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan, Pricing.Quote quote) {
    24	        this.id = id;
    25	        this.room = room;
    26	        this.guestName = guestName;
    27	        this.guestEmail = guestEmail;
    28	        this.identity = identity;
    29	        this.checkIn = checkIn;
    30	        this.checkOut = checkOut;
    31	        this.guests = guests;
    32	        this.ratePlan = ratePlan;
    33	        this.quote = quote;
    34	    }
    35	
    36	    public ReservationStatus status() { return status; }
    37	    public BigDecimal amountPaid() { return amountPaid; }
    38	    public BigDecimal refund() { return refund; }
    39	
    40	    /** O que ficou com a pousada: pago menos devolvido. */
    41	    public BigDecimal netAmount() {
    42	        return Money.round(amountPaid.subtract(refund == null ? Money.ZERO : refund));
    43	    }
    44	
    45	    /** Ocupa a noite (entra nela; quem sai naquele dia não conta). */
    46	    public boolean occupies(LocalDate night) {
    47	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    48	    }
    49	
    50	    public boolean overlaps(LocalDate in, LocalDate out) {
    51	        return checkIn.isBefore(out) && in.isBefore(checkOut);
    52	    }
    53	
    54	    public ReservationDocument document() {
    55	        return new ReservationDocument(id, guestName, identity, room.number(), room.type(),
    56	                checkIn, checkOut, quote.nights(), quote.subtotal(), quote.discount(), quote.total());
    57	    }
    58	}
=== Money
     1	package com.pousadamaretalta;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.util.Locale;
     6	
     7	/** Dinheiro: sempre 2 casas, arredondamento meio para o par. */
     8	public final class Money {
     9	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    10	
    11	    private Money() {}
    12	
    13	    public static BigDecimal round(BigDecimal v) {
    14	        return v.setScale(2, RoundingMode.HALF_EVEN);
    15	    }
    16	
    17	    public static BigDecimal of(String v) {
    18	        return round(new BigDecimal(v));
    19	    }
    20	
    21	    /** 1234.56 -> "R$ 1.234,56" */
    22	    public static String brl(BigDecimal v) {
    23	        String us = String.format(Locale.US, "%,.2f", round(v));
    24	        return "R$ " + us.replace(',', '#').replace('.', ',').replace('#', '.');
    25	    }
    26	
    27	    /** 1234.56 -> "BRL 1,234.56" */
    28	    public static String brlEn(BigDecimal v) {
    29	        return "BRL " + String.format(Locale.US, "%,.2f", round(v));
    30	    }
    31	}

