     1	package com.pousadamaretalta;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import java.math.BigDecimal;
     5	import java.time.LocalDate;
     6	import java.time.YearMonth;
     7	import java.util.ArrayList;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	import java.util.Map;
    11	import java.util.TreeMap;
    12	
    13	/** Regras de negócio, com os dados em memória. Todas as operações são serializadas. */
    14	public class ReservationService {
    15	    private final Map<Integer, Reservation> reservations = new TreeMap<>();
    16	    private final List<Message> outbox = new ArrayList<>();
    17	    private int nextReservationId = 1;
    18	
    19	    public List<Room> rooms() {
    20	        return Room.ALL;
    21	    }
    22	
    23	    public synchronized Reservation create(JsonNode body) {
    24	        String guestName = Json.requiredText(body, "guestName");
    25	        String guestEmail = Json.requiredText(body, "guestEmail");
    26	        GuestIdentity identity = IdentityReader.read(body);
    27	        int roomNumber = Json.requiredInt(body, "roomNumber");
    28	        LocalDate checkIn = Json.requiredDate(body, "checkIn");
    29	        LocalDate checkOut = Json.requiredDate(body, "checkOut");
    30	        int guests = Json.requiredInt(body, "guests");
    31	        RatePlan plan;
    32	        try {
    33	            plan = RatePlan.valueOf(Json.requiredText(body, "ratePlan"));
