     6	public final class Pricing {
     7	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     8	
     9	    private Pricing() {}
    10	
    11	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    12	
    13	    /** Alta temporada: 15/12 até fim de fevereiro, e julho inteiro. */
    14	    public static boolean isHighSeason(LocalDate night) {
    15	        int m = night.getMonthValue();
    16	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
    17	    }
    18	
    19	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    20	        BigDecimal rate = room.nightlyRate();
    21	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : rate;
    22	    }
    23	
    24	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    25	        BigDecimal subtotal = Money.ZERO;
    26	        int nights = 0;
    27	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    28	            subtotal = Money.round(subtotal.add(nightPrice(room, d)));
    29	            nights++;
    30	        }
    31	        BigDecimal discount = Money.round(subtotal.multiply(plan.discountRate));
    32	        BigDecimal total = Money.round(subtotal.subtract(discount));
    33	        return new Quote(nights, subtotal, discount, total);
    34	    }
    35	}
